async def _async_validate_users_yaml(
    hass: HomeAssistant,
    config_entry: ConfigEntry | None,
    raw_users: dict[Any, Any],
    locks: Iterable[str],
    *,
    taken: Mapping[str, Mapping[str, Any]] = MappingProxyType({}),
) -> tuple[dict | None, dict, dict]:
    """
    Validate a users submission for the editor and the yaml setup path.

    Slot numbers are not part of this shape at all: the editor names users,
    and the numbers are allocated afterwards from whatever the locks leave
    free. What can still fail is a name that is empty or that means the same
    person as another, and a count of users no lock could hold.

    ``config_entry`` is the entry the submission is for, or ``None`` from
    the flow that is still creating one; it is what the lock reads this
    performs are made on behalf of.

    ``taken`` is whichever users the block is being added alongside, empty
    when it IS the whole configuration. A block added to an entry has to
    clear the users already there as well as its own: two keys meaning one
    person collapse into a single key on the way into storage whether they
    arrived together or a week apart, and a credential two users share is
    recorded as either of them whoever presents it.

    Returns the parsed users -- or ``None`` when validation failed -- with the
    accumulated errors and description placeholders.
    """
    # A block still keyed by slot number coerces cleanly into users named
    # "1", "2", which is a silently wrong reading of what was pasted.
    if raw_users and all(isinstance(key, int) for key in raw_users):
        return None, {"base": "users_keyed_by_slot"}, {}

    try:
        parsed_users = USERS_SCHEMA(raw_users)
    except vol.Invalid as err:
        _LOGGER.error("Invalid users: %s", err)
        return None, {"base": "invalid_config"}, {}

    if problem := validate_user_names(parsed_users):
        name, error = problem
        return None, {"base": error}, {"name": name}

    spoken_for = {identity(name) for name in taken}
    for name in parsed_users:
        if identity(name) in spoken_for:
            return None, {"base": "name_not_unique"}, {"name": name}

    seen: dict[str, Mapping[str, Any]] = dict(taken)
    for name, fields in parsed_users.items():
        if duplicates := _duplicate_credentials(fields, seen):
            # Its own message: a block has no field to mark, so it names whose.
            credential = next(iter(duplicates))
            return None, {"base": f"{credential}_not_unique_in_block"}, {"name": name}
        seen[name] = fields

    # The same refusal the guided path gives. Both write the one field, so a
    # condition entity this integration cannot read must fail on both routes
    # or the editor becomes a way around the check.
    ent_reg = er.async_get(hass)
    for name, fields in parsed_users.items():
        if not (condition := fields.get(CONF_CONDITION)):
            continue
        entity_entry = ent_reg.async_get(condition)
        if entity_entry and entity_entry.platform in EXCLUDED_CONDITION_PLATFORMS:
            return (
                None,
                {"base": "excluded_platform"},
                {
                    "name": name,
                    "integration": entity_entry.platform,
                    "docs_url": (
                        "https://github.com/raman325/lock_code_manager/wiki/"
                        "Unsupported-Condition-Entity-Integrations"
                    ),
                },
            )

    # The count is what a lock has to hold, now that nobody picks a number --
    # everyone the entry will hold once this block lands, not just the block.
    wanted = len(taken) + len(parsed_users)
    try:
        await async_check_slot_capacity(hass, config_entry, locks, [wanted])
    except SlotAllocationError as err:
        return (
            None,
            {"base": "too_many_users"},
            {**err.placeholders, "num_users": str(wanted)},
        )
    return parsed_users, {}, {}


def _cannot_report(
    hass: HomeAssistant, locks: Iterable[str], slots: Iterable[int]
) -> dict[str, str] | None:
    """
    Name those of ``locks`` that cannot report their codes, and the slots at risk.

    None when every one of them can: nothing to warn of. Said, not asked:
    any lock would get these slots, and nothing seen in them may still be a
    keypad code.
    """
    if not (silent := locks_that_cannot_report(hass, locks)):
        return None
    return {
        "lock": ", ".join(silent),
        "slots": ", ".join(str(slot) for slot in sorted(slots)),
    }


_AllocationOutcome = tuple[frozenset[int] | None, dict[str, str], dict[str, Any]]


async def _allocate_for(
    hass: HomeAssistant,
    config_entry: ConfigEntry | None,
    locks: Sequence[str],
    num_users: int,
    *,
    held: Collection[int] = (),
    progress: Callable[[float], None] | None = None,
) -> _AllocationOutcome:
    """
    Find numbers for ``num_users``, or say why it could not.

    Allocation itself lives in ``ha.allocation``, which the services call
    too; this only turns its refusals into the form errors a flow renders.

    ``config_entry`` is the entry being allocated for, whose own numbers do
    not constrain it: kept ones are held by tenure, released ones are free
    for whoever comes next. A flow that is still creating its entry passes
    ``None``, which by the same rule holds nothing.
    """
    try:
        unavailable = await async_allocate_for(
            hass, config_entry, locks, num_users, held=held, progress=progress
        )
    except SlotAllocationError as err:
        return None, {"base": err.translation_key}, err.placeholders
    except Exception:
        # Runs as a flow progress task: an exception escaping here would
        # reach the user as "Unknown error" with nothing in the form.
        _LOGGER.exception("Allocating slot numbers on %s failed", ", ".join(locks))
        return None, {"base": "allocation_failed"}, {}
    return unavailable, {}, {}


def _validate_user_form(
    hass: HomeAssistant,
    user_input: dict[str, Any],
    taken: Mapping[str, Mapping[str, Any]],
    previous: Mapping[str, Any] = MappingProxyType({}),
    carried: Mapping[str, Any] = MappingProxyType({}),
) -> tuple[str | None, dict[str, Any], dict[str, str], dict[str, Any]]:
    """
    Validate one user's submitted form against the users already there.

    Shared by the setup flow, which collects users before the entry exists,
    and the subentry flow, which adds and edits them afterwards. One
    definition of a valid user, so the two routes cannot answer differently.

    ``taken`` is whichever users this submission must not collide with, by
    name or by credential -- for an edit, everybody except the user being
    edited, whose stored fields are ``previous``.

    ``carried`` is stored fields the form did not show, kept as they are.
    They are not a submission, so neither a value rule nor the duplicate
    check applies to them: the user could not change them, and an error on a
    field the form does not draw leaves a dialog that can never be
    submitted. They still count as the credential an enabled user needs.
    """
    errors: dict[str, str] = {}
    placeholders: dict[str, Any] = {}
    # Compared as it will be stored: a PIN is stripped where it enters.
    submitted = {**user_input, CONF_PIN: (user_input.get(CONF_PIN) or "").strip()}

    if _slot_enabled_without_credential({**submitted, **carried}):
        errors["base"] = "missing_credential_if_enabled"
    invalid = _credential_errors(submitted)
    errors.update(invalid)
    errors.update(
        {
            field: error
            for field, error in _duplicate_credentials(
                submitted, taken, previous
            ).items()
            if field not in invalid
        }
    )

    name: str | None = None
    if error := name_error(user_input.get(CONF_NAME)):
        errors[CONF_NAME] = error
    else:
        # Normalize BOTH sides. Comparing a stripped candidate against
        # unstripped stored names lets "Raman " and "Raman" both through in
        # one order but not the other.
        name = normalize_name(user_input[CONF_NAME])
        if any(other.casefold() == name.casefold() for other in taken):
            errors[CONF_NAME] = "name_not_unique"

    if entity_id := user_input.get(CONF_CONDITION):
        entity_entry = er.async_get(hass).async_get(entity_id)
        if entity_entry and entity_entry.platform in EXCLUDED_CONDITION_PLATFORMS:
            errors[CONF_CONDITION] = "excluded_platform"
            placeholders["integration"] = entity_entry.platform
            placeholders["docs_url"] = (
                "https://github.com/raman325/lock_code_manager/wiki/"
                "Unsupported-Condition-Entity-Integrations"
            )

    if errors:
        return None, {}, errors, placeholders

    # The widest form, so a password the caller carried or offered is kept.
    fields = _code_slot_schema(password=True)(
        {**user_input, **carried, CONF_NAME: name}
    )
    del fields[CONF_NAME]
    return name, fields, errors, placeholders


