async def test_config_flow_yaml_error(hass: HomeAssistant):
    """Test error handling in YAML based config flow."""
    flow_id = await _start_yaml_config_flow(hass)

    with _holding():
        result = await async_configure_flow(
            hass,
            flow_id,
            {CONF_USERS: {"User 1": {CONF_ENABLED: True, CONF_PIN: ""}}},
        )

    assert result["type"] == "form"
    assert result["step_id"] == "yaml"
    assert result["errors"] == {"base": "invalid_config"}


async def test_config_flow_ui_stores_a_padded_pin_stripped(
    hass: HomeAssistant, mock_lock_config_entry
):
    """
    A PIN typed with surrounding whitespace is persisted without it.

    A submitted code is stripped before it is matched, so padding kept on
    the stored side makes a credential nothing anybody can type will ever
    match -- and the guided form is where a stray space gets typed.
    """
    flow_id = await _start_config_flow(hass)
    await async_configure_flow(hass, flow_id, {"next_step_id": "ui"})
    result = await async_configure_flow(hass, flow_id, {CONF_NUM_USERS: 1})
    assert result["step_id"] == "code_slot"

    result = await async_configure_flow(
        hass, flow_id, {CONF_NAME: "User 1", CONF_ENABLED: True, CONF_PIN: " 1234 "}
    )

    assert result["type"] == "create_entry"
    assert flow_users(result) == {"User 1": {CONF_ENABLED: True, CONF_PIN: "1234"}}


async def test_config_flow_ui_rejects_a_whitespace_only_pin(
    hass: HomeAssistant, mock_lock_config_entry
):
    """
    An enabled user whose PIN is only whitespace is refused, not stored.

    Stripping happens before the enabled-needs-a-PIN check, so a PIN that
    is empty once stripped fails that check rather than being written as a
    credential no keypad can produce.
    """
    flow_id = await _start_config_flow(hass)
    await async_configure_flow(hass, flow_id, {"next_step_id": "ui"})
    await async_configure_flow(hass, flow_id, {CONF_NUM_USERS: 1})

    result = await async_configure_flow(
        hass, flow_id, {CONF_NAME: "User 1", CONF_ENABLED: True, CONF_PIN: "   "}
    )

    assert result["type"] == "form"
    assert result["step_id"] == "code_slot"
    assert result["errors"] == {"base": "missing_credential_if_enabled"}


async def test_config_flow_yaml_stores_a_padded_pin_stripped(
    hass: HomeAssistant, mock_lock_config_entry
):
    """A pasted block's padded PIN is persisted stripped, as the form's is."""
    flow_id = await _start_yaml_config_flow(hass)

    with _holding():
        result = await async_configure_flow(
            hass,
            flow_id,
            {CONF_USERS: {"User 1": {CONF_ENABLED: True, CONF_PIN: " 1234 "}}},
        )

    assert result["type"] == "create_entry"
    assert flow_users(result) == {"User 1": {CONF_ENABLED: True, CONF_PIN: "1234"}}


async def test_config_flow_yaml_rejects_a_whitespace_only_pin(
    hass: HomeAssistant, mock_lock_config_entry
):
    """A pasted block's whitespace-only PIN on an enabled user is refused."""
    flow_id = await _start_yaml_config_flow(hass)

    with _holding():
        result = await async_configure_flow(
            hass,
            flow_id,
            {CONF_USERS: {"User 1": {CONF_ENABLED: True, CONF_PIN: "   "}}},
        )

    assert result["type"] == "form"
    assert result["step_id"] == "yaml"
    assert result["errors"] == {"base": "invalid_config"}


async def test_config_flow_yaml_takes_an_empty_password_as_none(
    hass: HomeAssistant, mock_lock_config_entry
):
    """An empty password means none, as an empty PIN does, and both are kept so."""
    flow_id = await _start_yaml_config_flow(hass)

    with _holding():
        result = await async_configure_flow(
            hass,
            flow_id,
            {
                CONF_USERS: {
                    "User 1": {CONF_ENABLED: True, CONF_PIN: "1234", "password": ""},
                    "User 2": {CONF_ENABLED: False, CONF_PIN: "", "password": ""},
                }
            },
        )

    assert result["type"] == "create_entry"
    assert flow_users(result) == {
        "User 1": {CONF_ENABLED: True, CONF_PIN: "1234", "password": ""},
        "User 2": {CONF_ENABLED: False, CONF_PIN: "", "password": ""},
    }


async def test_config_flow_yaml_rejects_a_whitespace_only_password(
    hass: HomeAssistant, mock_lock_config_entry
):
    """Spaces alone are not empty: the password rule refuses them."""
    flow_id = await _start_yaml_config_flow(hass)

    with _holding():
        result = await async_configure_flow(
            hass,
            flow_id,
            {
                CONF_USERS: {
                    "User 1": {CONF_ENABLED: True, CONF_PIN: "1234", "password": "  "}
                }
            },
        )

    assert result["type"] == "form"
    assert result["errors"] == {"base": "invalid_config"}


async def test_options_flow_edits_the_locks(
    hass: HomeAssistant, mock_lock_config_entry
):
    """The options flow edits the entry's locks and leaves its users alone."""

